describe('Form Submission Error Scroll Into View', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.viewport(1280, 720);
  });

  it('should scroll error message into view when form submission fails', () => {
    // Scroll to bottom of page to ensure error field is out of view
    cy.scrollTo('bottom');

    // Fill form with invalid data
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('input[name="password"]').type('123');

    // Submit form
    cy.get('button[type="submit"]').click();

    // Wait for error message to appear
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify error message is scrolled into view
    cy.get('[data-testid="error-message"]').then(($element) => {
      const rect = $element[0].getBoundingClientRect();
      expect(rect.top).to.be.greaterThan(0);
      expect(rect.top).to.be.lessThan(window.innerHeight);
    });

    // Verify error text content
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email');
  });

  it('should scroll multiple errors into view and focus on first error field', () => {
    // Scroll page to middle
    cy.scrollTo('center');

    // Leave required fields empty
    cy.get('input[name="firstName"]').clear();
    cy.get('input[name="lastName"]').clear();
    cy.get('input[name="email"]').clear();
    cy.get('input[name="phone"]').clear();

    // Submit form
    cy.get('button[type="submit"]').click();

    // Wait for error container to be visible
    cy.get('[data-testid="error-container"]').should('be.visible');

    // Verify first error field is in viewport
    cy.get('input[name="firstName"]').then(($element) => {
      const rect = $element[0].getBoundingClientRect();
      expect(rect.top).to.be.greaterThan(-1);
      expect(rect.top).to.be.lessThan(window.innerHeight + 1);
    });

    // Verify all error messages are present
    cy.get('[data-testid="error-item"]').should('have.length.greaterThan', 1);

    // Verify first error field receives focus
    cy.get('input[name="firstName"]').should('have.focus');
  });

  it('should handle edge case where error appears above viewport', () => {
    // Create a form with error at the very top
    cy.get('input[name="email"]').type('invalid@');

    // Scroll to bottom to move error out of view
    cy.scrollTo('bottom');

    // Submit form
    cy.get('button[type="submit"]').click();

    // Verify error scrolls into view from above
    cy.get('[data-testid="email-error"]').should('be.visible');

    // Verify scroll position changed
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(0);
    });
  });

  it('should handle edge case with very long error messages', () => {
    // Fill form with data that triggers long error message
    cy.get('input[name="password"]').type('a');
    cy.get('input[name="confirmPassword"]').type('b');

    // Submit form
    cy.get('button[type="submit"]').click();

    // Verify long error message is fully visible
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').then(($element) => {
      const rect = $element[0].getBoundingClientRect();
      const elementHeight = rect.height;
      const bottomPosition = rect.bottom;

      expect(bottomPosition).to.be.lessThan(window.innerHeight);
      expect(elementHeight).to.be.greaterThan(0);
    });
  });

  it('should not scroll when error is already in viewport', () => {
    // Get initial scroll position
    let initialScrollY;
    cy.window().then((win) => {
      initialScrollY = win.scrollY;
    });

    // Fill form with invalid data (error field visible)
    cy.get('input[name="email"]').type('invalid');

    // Submit form
    cy.get('button[type="submit"]').click();

    // Verify error is visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify scroll position remained relatively unchanged
    cy.window().then((win) => {
      expect(Math.abs(win.scrollY - initialScrollY)).to.be.lessThan(100);
    });
  });
});
